<?php
declare(strict_types=1);
define('SAAS_NO_GLOBAL_NAV', true); require_once __DIR__ . '/finance.php'; require_finance_admin();
$pdo=db();$month=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['month']??''))?$_GET['month']:date('Y-m');$from=$month.'-01';$to=date('Y-m-d',strtotime($from.' +1 month'));
$q=$pdo->prepare('SELECT COALESCE(SUM(amount_received),0) FROM client_payments WHERE invoice_date>=? AND invoice_date<?');$q->execute([$from,$to]);$income=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(net_salary),0) FROM salary_payroll WHERE month_year=?');$q->execute([$month]);$salary=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM office_expenses WHERE date>=? AND date<?');$q->execute([$from,$to]);$expenses=(float)$q->fetchColumn();$q=$pdo->prepare("SELECT COALESCE(SUM(net_salary),0) FROM salary_payroll WHERE month_year=? AND payment_status='Paid'");$q->execute([$month]);$paidSalary=(float)$q->fetchColumn();$receivable=(float)$pdo->query('SELECT COALESCE(SUM(invoice_amount-amount_received),0) FROM client_payments WHERE amount_received<invoice_amount')->fetchColumn();$active=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='employee' AND active=1")->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) total,SUM(status='present') present FROM attendance WHERE date>=? AND date<?");$q->execute([$from,$to]);$att=$q->fetch();$attendance=$att['total']?round(((int)$att['present']/(int)$att['total'])*100,1):0;$outflow=$paidSalary+$expenses;$net=$income-$outflow;$labels=[];$incomes=[];$expenseChart=[];for($i=5;$i>=0;$i--){$m=date('Y-m',strtotime($from.' -'.$i.' months'));$labels[]=$m;$q=$pdo->prepare('SELECT COALESCE(SUM(amount_received),0) FROM client_payments WHERE DATE_FORMAT(invoice_date,?)=?');$q->execute(['%Y-%m',$m]);$incomes[]=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM office_expenses WHERE DATE_FORMAT(date,?)=?');$q->execute(['%Y-%m',$m]);$expenseChart[]=(float)$q->fetchColumn();}function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finance Dashboard</title><link rel="stylesheet" href="assets/css/saas.css"><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><div class="nav-label">Workspace</div><a class="saas-nav" href="admin_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav active" href="finance_dashboard.php">◈ <span>Finance</span></a><a class="saas-nav" href="manage_clients.php">♙ <span>Clients</span></a><a class="saas-nav" href="manage_users.php">♟ <span>Users</span></a><div class="nav-label">Operations</div><a class="saas-nav" href="admin_attendance.php">◷ <span>Attendance</span></a><a class="saas-nav" href="staff_master.php">♙ <span>Staff Master</span></a><a class="saas-nav" href="payroll.php">▤ <span>Payroll</span></a><a class="saas-nav" href="invoices.php">▧ <span>Invoices</span></a><a class="saas-nav" href="expenses.php">▣ <span>Expenses</span></a><a class="saas-nav" href="cashflow.php">↗ <span>Cash flow</span></a><div class="nav-label">Account</div><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><header class="saas-topbar"><div><h1 class="saas-title">Finance overview</h1><div class="saas-subtitle">Track income, payroll, expenses and cash position.</div></div><div class="saas-toolbar"><form><input class="month-pill" type="month" name="month" value="<?=e($month)?>"><button class="btn-indigo" type="submit">Apply</button></form><div class="avatar">A</div></div></header><section class="kpi-grid"><div class="kpi-card income"><div class="kpi-icon green">↗</div><div class="kpi-label">Client income</div><div class="kpi-value"><?=inr($income)?></div><div class="trend">▲ Current month</div></div><div class="kpi-card"><div class="kpi-icon amber">▤</div><div class="kpi-label">Salary payable</div><div class="kpi-value"><?=inr($salary)?></div><div class="trend muted">Payroll total</div></div><div class="kpi-card expense"><div class="kpi-icon red">↘</div><div class="kpi-label">Office expenses</div><div class="kpi-value"><?=inr($expenses)?></div><div class="trend muted">Current month</div></div><div class="kpi-card expense"><div class="kpi-icon red">−</div><div class="kpi-label">Cash outflow</div><div class="kpi-value"><?=inr($outflow)?></div><div class="trend muted">Paid salary + expenses</div></div><div class="kpi-card income"><div class="kpi-icon green">₹</div><div class="kpi-label">Net remaining cash</div><div class="kpi-value"><?=inr($net)?></div><div class="trend">Income minus outflow</div></div><div class="kpi-card"><div class="kpi-icon amber">◷</div><div class="kpi-label">Pending receivables</div><div class="kpi-value"><?=inr($receivable)?></div><div class="trend muted">Outstanding invoices</div></div><div class="kpi-card"><div class="kpi-icon green">✓</div><div class="kpi-label">Paid salaries</div><div class="kpi-value"><?=inr($paidSalary)?></div><div class="trend muted">This month</div></div><div class="kpi-card"><div class="kpi-icon">♙</div><div class="kpi-label">Active staff</div><div class="kpi-value"><?=number_format($active)?></div><div class="trend muted">Team members</div></div></section><section class="chart-grid"><div class="saas-card"><h2>Income vs expenses</h2><canvas id="incomeChart" height="110"></canvas></div><div class="saas-card"><h2>Attendance</h2><div class="kpi-value"><?=e((string)$attendance)?>%</div><div class="saas-subtitle">Overall attendance this month</div></div></section></main></div><script>new Chart(document.getElementById('incomeChart'),{type:'bar',data:{labels:<?=json_encode($labels)?>,datasets:[{label:'Income',data:<?=json_encode($incomes)?>,backgroundColor:'#6366f1',borderRadius:8},{label:'Expenses',data:<?=json_encode($expenseChart)?>,backgroundColor:'#ef4444',borderRadius:8}]},options:{responsive:true,animation:{duration:800},plugins:{legend:{labels:{usePointStyle:true}}},scales:{y:{beginAtZero:true,grid:{color:'#eef2f7'}},x:{grid:{display:false}}}}});</script></body></html>
